package local.codex.voyahcameratest;

import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;

/** Opt-in on-device smoke test. Power Hold stays disabled: this never sends vehicle commands. */
public final class Smoke extends Instrumentation {
  Activity activity;JSONArray checks=new JSONArray();
  interface Condition {boolean check(JSONObject state)throws Exception;}
  public void onCreate(Bundle args){super.onCreate(args);start();}
  JSONObject state()throws Exception{return new JSONObject(new String(java.nio.file.Files.readAllBytes(new File(getTargetContext().getExternalFilesDir(null),"state.json").toPath()),StandardCharsets.UTF_8));}
  int id(String name){return getTargetContext().getResources().getIdentifier(name,"id","local.codex.voyahcameralab");}
  void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
  JSONObject waitFor(String name,Condition condition)throws Exception{long end=SystemClock.elapsedRealtime()+18000;JSONObject last=null;while(SystemClock.elapsedRealtime()<end){last=state();if(condition.check(last)){checks.put(new JSONObject().put("check",name).put("state",last));Bundle progress=new Bundle();progress.putString("stream","PASS: "+name+"\n");sendStatus(0,progress);return last;}SystemClock.sleep(250);}throw new AssertionError(name+" "+last);}
  void launch(boolean manual){Intent intent=new Intent(Intent.ACTION_MAIN).setClassName("local.codex.voyahcameralab","local.codex.voyahcameralab.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(manual)intent.putExtra("auto_record",false);activity=startActivitySync(intent);}
  void finishActivity(){runOnMainSync(()->activity.finish());waitForIdleSync();SystemClock.sleep(700);}
  void click(String name){runOnMainSync(()->{View v=activity.findViewById(id(name));check(v!=null&&v.isEnabled(),"Control missing/disabled: "+name);v.performClick();});waitForIdleSync();}
  AlertDialog dialog()throws Exception{java.lang.reflect.Field f=activity.getClass().getDeclaredField("settingsDialog");f.setAccessible(true);return (AlertDialog)f.get(activity);}
  void checkSettings()throws Exception{
    click("settings_button");AlertDialog d=dialog();check(d!=null,"Settings open");
    runOnMainSync(()->{check(((CheckBox)d.findViewById(id("auto_record_checkbox"))).isChecked(),"Auto-record default enabled");check(!((CheckBox)d.findViewById(id("power_hold_checkbox"))).isChecked(),"Power Hold stays off");check(((Spinner)d.findViewById(id("power_duration_picker"))).getSelectedItemPosition()==3,"Power duration default 120 minutes");check(((Spinner)d.findViewById(id("storage_policy_picker"))).getSelectedItemPosition()==0,"Cycle storage default");check(((Spinner)d.findViewById(id("storage_percent_picker"))).getSelectedItemPosition()==8,"Storage default 90 percent");check(((Spinner)d.findViewById(id("segment_picker"))).getSelectedItemPosition()==0,"Segment default one minute");check(!d.findViewById(id("camera_picker")).isShown(),"Diagnostic source initially hidden");d.findViewById(id("advanced_settings_button")).performClick();check(d.findViewById(id("camera_picker")).isShown(),"Additional source selector exists");check(d.findViewById(id("view_picker"))==null&&d.findViewById(id("crop_checkbox"))==null,"Lite has no old view/crop controls");d.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();});waitForIdleSync();
  }
  public void onStart(){Bundle result=new Bundle();JSONObject report=new JSONObject();try{
    SharedPreferences prefs=getTargetContext().getSharedPreferences("camera",0);prefs.edit().putBoolean("adaptive_views",false).remove("auto_record").remove("legacy_padding_correction").remove("power_hold_minutes").remove("segment_seconds").remove("storage_policy").remove("max_storage_percent").putBoolean("power_hold",false).putString("camera_id","1").putInt("view",2).putBoolean("camera_only",true).putBoolean("trim_padding",true).commit();
    launch(true);waitFor("explicit manual launch previews full frame despite legacy crop/view preferences",s->s.getBoolean("opening")&&s.getLong("frames")>=3&&!s.getBoolean("recording")&&s.getBoolean("fullFrame"));checkSettings();
    click("record_button");waitFor("manual recording starts",s->s.getBoolean("recording"));SystemClock.sleep(12000);check(state().getBoolean("recording"),"Recording continues beyond ten seconds");click("stop_button");waitFor("stop completes MP4 and preserves preview",s->!s.getBoolean("recording")&&!s.getBoolean("recordStopping")&&s.getBoolean("opening")&&!s.isNull("lastVideo"));
    runOnMainSync(()->{View root=((ViewGroup)activity.findViewById(android.R.id.content)).getChildAt(0);ViewGroup.LayoutParams lp=root.getLayoutParams();lp.width=600;lp.height=320;root.setLayoutParams(lp);});waitForIdleSync();SystemClock.sleep(700);
    runOnMainSync(()->{View root=((ViewGroup)activity.findViewById(android.R.id.content)).getChildAt(0);int[] rp=new int[2];root.getLocationOnScreen(rp);for(String name:new String[]{"record_button","stop_button","video_button"}){View b=activity.findViewById(id(name));int[] bp=new int[2];b.getLocationOnScreen(bp);check(b.getWidth()>0&&bp[1]>=rp[1]&&bp[1]+b.getHeight()<=rp[1]+root.getHeight(),"Controls fit 600x320: "+name);}});
    finishActivity();launch(false);waitFor("new launch defaults to automatic recording",s->s.getBoolean("recording")&&s.getBoolean("autoRecordOnOpen")&&!s.getBoolean("powerHoldEnabled"));click("stop_button");waitFor("explicit stop disarms automatic launch",s->!s.getBoolean("recording")&&!s.getBoolean("autoRecordPending"));
    ActivityMonitor monitor=addMonitor("local.codex.voyahcameralab.MainActivity",null,false);runOnMainSync(()->activity.recreate());Activity replacement=waitForMonitorWithTimeout(monitor,10000);removeMonitor(monitor);check(replacement!=null,"Activity recreation completes");activity=replacement;waitForIdleSync();waitFor("recreation after Stop previews without rearming",s->s.getBoolean("opening")&&s.getLong("frames")>=3&&!s.getBoolean("recording")&&!s.getBoolean("autoRecordPending"));
    finishActivity();waitFor("hidden activity releases camera and recording",s->!s.getBoolean("opening")&&!s.getBoolean("recording"));report.put("passed",true).put("checks",checks);result.putString("stream",report.toString(2));finish(Activity.RESULT_OK,result);
  }catch(Throwable error){try{getTargetContext().getSharedPreferences("camera",0).edit().putBoolean("power_hold",false).putBoolean("auto_record",false).commit();if(activity!=null)finishActivity();report.put("passed",false).put("error",error.toString()).put("checks",checks);result.putString("stream",report.toString(2));}catch(Exception ignored){}finish(Activity.RESULT_CANCELED,result);}}
}
